import React, { useEffect, useState, useRef } from "react";
import "./Products.css";
import "./This_tailwind.css"

import { useStateValue } from "../StateProvider";
import ProductCard from "./ProductCard";
import { Link } from "react-router-dom";

const products = [
        {id: 1, name: "Sky Blu", price: 20, color: '#87CEEB', desc: 'Test1'},
        {id: 2, name: "Sun Orange", price: 30, color: '#FF4500', desc: 'Test2'}

    ]

    const Products = () => (
        <div className='dashboard_body'>

                <div className="wrapper">
                    <div className="wrapper-outside nothing" id="temp_dashboard_show_card">
                        {
                            products.map(p => (
                                <div className="container" >
                                        <h3 className="temp-card-title ">{p.name}</h3>
                                        <div style = {{backgroundColor: p.color, height: 100, width: 100}}></div>
                                        <p>${p.price}</p>
                                        <Link to = {`/product/${p.id}`}>See More</Link>
                                    </div>
                            ))
                        }


                        
                        </div>
                        
                    </div>
        </div>

    )

export default Products;
