import { useEffect, useRef, useState } from "react";
import "./Header.css";
import { useStateValue } from "../StateProvider";
import { auth } from "../config/Firebase";
import { Link, useNavigate } from "react-router-dom";
import reducer_s from "../reducer";
import Three_D_Temp from "../views/3D copy";
function Header() {
  const navigate = useNavigate();

  const navRef = useRef();
  //const [{ user, cond_test }, dispatch] = useStateValue();
  const [{user, condition_reducer, user_email, user_color, user_point_text, test}, dispatch] = useStateValue();

  const [condition, setCondition] = useState(null);

  useEffect(() => {
    const savedCondition = localStorage.getItem('condition');
    setCondition(savedCondition);
  
  })

  const showNavbar = () => {
    navRef.current.classList.toggle("responsive_nav");
    if (user_color !== null || user_point_text != null || test != null){
        
      dispatch({
        type: "SET_COLOR",
        user: null
        });
      dispatch({
        type: "SET_POINT_TEXT",
        user: null
        });
      dispatch({
        type: "SET_TEST",
        user: null
        });
  };}

  const handleAuthenticaton = () => {
    if (user) {
      //navigate("/react-project");
      dispatch({
        type: "SET_CONDITION_REDUCER",
        user: null
      });

      localStorage.removeItem('userEmail');
      localStorage.removeItem('firebases-token');
      sessionStorage.removeItem('condition');
      auth.signOut();

    }
    showNavbar();
  };

  //console.log(user)
  //console.log(cond_test)
  const [cond1,setCond1] = useState(false) //temporary to remove the dashboard while fixing the layout

  return (
    <div className="navbar">
      <header>
   

        <nav ref={navRef}>
          <Link onClick={showNavbar} to="/NewTesting" className="nav-element">
            <p>Home</p>
          </Link>

          {user ? (
            condition ? (
              <Link onClick={showNavbar} to="/Products" className="nav-element">
                <p>Products</p>
              </Link>
            ) : null
          ) : null}

          {user ? (
            condition ? (
              <Link onClick={showNavbar} to="/Cart" className="nav-element">
                <p>Cart</p>
              </Link>
            ) : null
          ) : null}

          
          {user ? (
            condition ?
            (
              <Link onClick={showNavbar} to="/PO_Forecast" className="nav-element">
                <p>Product Forecast</p>
              </Link>
            ) : null
          ): null}

          {user ? (
            condition ? (
              <Link onClick={showNavbar} to="/requisition" className="nav-element hide">
                <p>Requisition</p>
              </Link>
            ) : null
          ) : null}
          

          {user ? (
            condition ? (
              <Link onClick={showNavbar} to="/about" className="nav-element hide">
                <p>About</p>
              </Link>
            ) : null
          ) : null}

          {user ? (
            !condition ? (
              <Link onClick={showNavbar} to="/OTP_Glass" className="nav-element">
                <p>OTP_Authentication</p>
              </Link>
            ) : null
          ) : null}

          {user ? (
            condition ? (
              <Link onClick={showNavbar} className="nav-element hid hide">
                <label className="switch">
                  <input type="checkbox"/>
                  <span className="slider round"></span>
                </label>              
              </Link>
            ) : null
          ) : null}

          <Link to={!user && "/login_card"} className="nav-element">
            <div onClick={handleAuthenticaton} className="signin_but">
              <p>{user ? "Sign Out" : "Sign In"}</p>
            </div>
          </Link>

          <button className="nav-btn nav-close-btn" onClick={showNavbar}>
           
          </button>
        </nav>
        <button className="nav-btn" onClick={showNavbar}>
          Menu
        </button>
      </header>
    </div>
  );
}

export default Header;


//{user ? (condition ? (<Link onClick={showNavbar} to="/3D_Model" className="nav-element"><p>3D Model</p></Link>) : null) : null}