import React, { useEffect, useState, useRef } from "react";
//import "./Products.css";
import "./This_tailwind.css"

import { useStateValue } from "../StateProvider";

import { Face } from "three/examples/jsm/Addons.js";
import { Link, useParams } from "react-router-dom";

const productData = {
    1: {name: "Sky Blu", price: 20, color: '#87CEEB', desc: 'Test1'},
    2: {name: "Sun Orange", price: 30, color: '#FF4500', desc: 'Test2'}
}

const ProductDetails = ({addToCart}) => {
    const {id} = useParams();
    const product = productData[id];

    const [quantity, setQuantity] = useState(1);
    const [added, setAdded] = useState(false);

    const [color, setColor] = useState(product.color);

    const handleAddToCart = () => {
        addToCart({...product, quantity});

        setAdded(true)

        setTimeout(() => setAdded(false), 10000) //after 10s
    }

    return (



        

    <div className="forecast-body">
        <div class="forecast-wrapper" id ="forecast-panel">
            <h5 className="forecast-h1">{product.name}</h5>
                <div style = {{backgroundColor: color, height: 100, width: 100}}></div>
                    <p>{product.desc}</p>
                    <p>${product.price}</p>
            <div className="input-field">
                <input className="OTP-input" type='text' value ={quantity} onChange={(e) => setQuantity(Number(e.target.value))}/>
                <label>Quantity</label>

            </div>
            <div className="input-field">
                <input type='color' className="OTP-input" value = {color} onChange={(e) => setColor(e.target.value)}></input>
                <label>Color</label>

            </div>
                <div className="OTP-butt">
                    <button onClick={handleAddToCart} className="forecast-button" disabled={added}>
                        {added ? 'Added!' : 'Add To Cart'}
                    </button>
                </div>
            </div>
    </div>




    )

}

export default ProductDetails;
