import React, { useEffect, useState } from "react";
import "./App.css";
import Home from "./views/Home";
//import Login from "./views/Login";


import Login_Card from "./views/Credit_Card";


import Register_Card from "./views/Register_Credit_Card";

import Register from "./views/Register";



import Header from "./components/Header";
import Protected from "./components/Protected";




import PO_Forecast from "./views/PO_Forecast";


import Requisition from "./views/Requisition";

import ML from "./views/ML";

import OTP_Login from "./views/OTP_Authentication";

import OTP_Glass from "./views/OTP_Glass";


//import Three_D from "./views/3D";

import About from "./views/About";

import { BrowserRouter as Router, Route, Routes } from "react-router-dom";
import { useStateValue } from "./StateProvider";
import { auth } from "./config/Firebase";
import { cond } from "three/webgpu";

import {useNavigate} from  "react-router-dom";
import { update } from "plotly.js";
import CartPage from "./views/ProductCartPage";
import Products from "./views/Products";
import ProductDetails from "./views/ProductDetails";
import Product_Forecast from "./views/Product_Forecast";

function App() {
  const [isSignedIn, setIsSignedIn] = useState(null);
  const [condition, setCondition] = useState(null);

  const [{user, condition_reducer}, dispatch] = useStateValue();

  const [condition_1, setCondition_1] = useState(false);

  useEffect(() => {
    const savedCondition = localStorage.getItem('condition');
    setCondition_1(savedCondition);
    //console.log(savedCondition)
  
  })

  useEffect(() => {
    // will only run once when the app component loads...
    if (condition_1){
      
      setCondition(true);
      //console.log(user.condition_reducer)
      }
    }, [condition_1]);
 



    useEffect(() => {
      // will only run once when the app component loads...
  
      auth.onAuthStateChanged(async(authUser) => {  
        if (authUser) {
          // the user just logged in / the user was logged in
          
          dispatch({
            type: "SET_USER",
            user: authUser
          });
          setIsSignedIn(true);
          try {
            const token = await authUser.getIdToken(true);
            //console.log(token)
            localStorage.setItem('firebases-token', token)  
          }
          catch(error){
            console.log(error)
          }
        } else {
          // the user is logged out
          dispatch({
            type: "SET_USER",
            user: null
          });
          setIsSignedIn(false);
        }
      });
    }, []);

    const [Cart, setCart] = useState([])

    const addToCart = (newItem) => {
      setCart(prevCart => {
        const existingIndex = prevCart.findIndex(item => item.id === newItem.id)
        if (existingIndex !== -1){
          const updatedCart = [...prevCart];
          updatedCart[existingIndex].quantity += newItem.quantity;
          return updatedCart;
        }
        return [...prevCart, newItem];
      })
    }

 

  return (
    <div>
      {isSignedIn !== null &&
      //condition_1 !== null &&
      (
        <Router>
          <div className="app">
            <Routes>
              <Route
                exact
                path="/NewTesting"
                element={
                  <div>
                    <Header />
                    <Home />
                  </div>
                }
              />

              <Route
                exact
                path="/Products"
                element={
                  <Protected isSignedIn={condition_1}>
                    <div>
                      <Header />
                      <Products/>
                    </div>
                  </Protected>
                }
              />

              <Route
                exact
                path="/product/:id"
                element={
                  <Protected isSignedIn={condition_1}>
                    <div>
                      <Header />
                      <ProductDetails addToCart={addToCart}/>
                    </div>
                  </Protected>
                }
              />

<Route
                exact
                path="/Cart"
                element={
                  <Protected isSignedIn={condition_1}>
                    <div>
                      <Header />
                      <CartPage cart = {Cart}/>
                    </div>
                  </Protected>
                }
              />


              
            <Route
                exact
                path="/PO_Forecast"
                element={
                  <Protected isSignedIn={condition_1}>
                    <div>
                      <Header />
                      <Product_Forecast />
                    </div>
                  </Protected>
                }
              />

              <Route
                exact
                path="/requisition"
                element={
                  <div>
                    <Header />
                    <Requisition />
                  </div>
                }
              />

              

<Route
                exact
                path="/about"
                element={
                  <Protected isSignedIn={condition_1}>
                    <div>
                      <Header />
                      <About />
                    </div>
                  </Protected>
                }
              />

              <Route
                exact
                path="/OTP_Glass"
                element={
                  <Protected isSignedIn={isSignedIn}>
                    <div>
                      <OTP_Glass />
                    </div>
                  </Protected>
                }
              />
              
              
              <Route exact path="/login_card" element={<Login_Card />} />
              <Route exact path="/register_card" element={<Register_Card />} /> 
            </Routes>
          </div>
        </Router>
      ) }
    </div>
  );
}

export default App;


