import React, { useEffect, useState } from "react";
import Plot from 'react-plotly.js';

function TrendlineBar({xaxis,yaxis, ybar,xname, yname, name, width, height, axis_color = '#efefef'}){
  
  const [temp, setTemp] = useState();
  const [control, setControl] = useState(false);
  
  const handleGraph1click = (e) => {

    const category = e.points[0].x;
    
    setTemp(category);
    setControl(true);} 

  useEffect(() => {
    if (control !== false){
        console.log(temp, 'this is from component')
        setControl(false)
    }

  }, [control])
  
  return (
        <Plot className='data-delivery'
        data={[
          {type:'bar', x:xaxis , y: ybar, name:'Value'},

          {
            x: xaxis,
            y: yaxis,
            type: 'scatter',
            mode: 'lines+markers',
            marker: {color: 'red'},
            name: 'Orders',
            yaxis: 'y2'
          },
          
        ]}
        layout={ {width: width, height: height, 
          
        title: {
            text: name,
            font: {
              family: 'Arial, sans-serif',
              //size: 24,
              color: axis_color, // Set the color of the title
            },
        },
          
        legend : {
          font: {
            //family: 'Arial, sans-serif',
            //size: 14,
            color: axis_color, // Set the color of the legend text
          },
          orientation: 'h',
          x: 0.2,
          y: 1.3
        },
        xaxis: {
          title: {
            text: xname,
            font: {
            //family: 'Arial, sans-serif',
            //size: 18,
            color: axis_color, // Set the color of the y-axis title
            },
          },
          tickfont: {
            //family: 'Arial, sans-serif',
            //size: 14,
            color: axis_color, // Set the color of the y-axis numbers
          },
         },
         yaxis2: {
            title: {
              text: 'yaxis2 title',
              font: {
              //family: 'Arial, sans-serif',
              //size: 18,
              color: axis_color, // Set the color of the y-axis title
              },
            },
            tickfont: {
              //family: 'Arial, sans-serif',
              //size: 14,
              color: axis_color, // Set the color of the y-axis numbers
            },
         },
          yaxis: {
                title: yname ,
                titlefont: {color: axis_color},
                tickfont: {color: axis_color},
                overlaying: 'y',
                side: 'right'
          },
          paper_bgcolor:'rgba(0,0,0,0)',
          plot_bgcolor:'rgba(0,0,0,0)'

        } }

        onClick={handleGraph1click}
      />
    )
}


export default TrendlineBar;