import React, { useState, useEffect, useRef } from "react";
import emailjs from '@emailjs/browser'; //have to npm install @emailjs/browser
import "./PO_Forecast.css";
import { Link, useNavigate } from "react-router-dom";
//import { signInWithEmailAndPassword } from "firebase/auth";
import { auth } from "../config/Firebase";
import { useStateValue } from "../StateProvider";
import Trendline from "./PlotTrendLine";

function Product_Forecast() {

  const [height, setHeight] = useState(0);
  const [width, setWidth] = useState(0);

  const [lookup_windows, setLookup_windows] = useState(0);


  const [result, setResult] = useState(0);
  const [date_list, setDate_List] = useState();
  const [hidden, setHidden] = useState(1);

  //useEffect(() => {
    // Reset the state to the default value when the component mounts
    //setHidden(1);
  //}, []);
  
  const handleSubmit = async(event) => {
        event.preventDefault();
        const status = 'success';
        if (status === 'success'){
            setResult(width*100 + height*10);
            if (hidden === 1){
              setHidden(0);
            }
            else{
              setHidden(1);}

        }
        else{
            alert ('Error');
        }

        }



  const handleForecastHidden = () => {
      if (hidden === 0){
          setHidden(1);
          setResult(0);
      }
      else{
          setHidden(0);
      }
  }

  //useEffect(()=>{
    //if(result !== null ){
      //setHidden(0);
    //}
    //else{
      //setHidden(1);
    //}
  //}, [result])



    useEffect(() => {

      let hide_button = document.getElementById('forecast-result')
      let show_button = document.getElementById('forecast-panel')

      if(hidden === 1 && hide_button && show_button)
      {
          //this is when hidden True
          //hide add
          hide_button.classList.add('forecast-hidden')
          //hidden_card.classList.add('hidden_show')

          //hide remove
          show_button.classList.remove('forecast-hidden')  //once user enter Send_email, which will set the OTP code, it will remove the button away
      }
      else if (hidden !== 1 && hide_button && show_button){
          //this is when hidden false
          //show removal
          show_button.classList.add('forecast-hidden') //once user enter Send_email, which will set the OTP code, it will remove the button away

          //hide removal
          hide_button.classList.remove('forecast_nothing_hidden')
          hide_button.classList.remove('forecast-hidden')

      }
    },[hidden])
  

  console.log('***')
  console.log(result)
  console.log(date_list)  
  console.log('***')

  return (
    <div className="forecast-body">
      <div class="forecast-wrapper" id ="forecast-panel">
      <form className="OTP-form" onSubmit={handleSubmit}>
      <h5 className="forecast-h1">Forecast Panel</h5>

            <div className="input-field">
            <input className="OTP-input" type='text' value = {height} onChange={(e) => setHeight(e.target.value)}/>
            <label>Room Height</label>
            </div>

            <div className="input-field">
            <input className="OTP-input" type='text' value = {width} onChange={(e) => setWidth(e.target.value)}/>
            <label>Room Width</label>
            </div>
            <div className="OTP-butt">
              <button type="submit" className="forecast-button">Forecast</button>
            </div>
        </form>
      </div>

      <div id = "forecast-result" class="forecast-wrapper forecast_nothing_hidden">
          <button className="forecast-filter-button" onClick={handleForecastHidden}>
                Panel
            </button>
          <h5 className="forecast-h1">Forecast Result</h5>
          <h5 className="forecast-h1">{result}</h5>

      </div>

    </div>
  );
}

export default Product_Forecast;

